        for (uint256 i; i < length; ++i) {
            _transferToken(s, from, to, ids[i], values[i]);
        }

        emit TransferBatch(sender, from, to, ids, values);

        if (to.hasBytecode()) {
            _callOnERC1155BatchReceived(sender, from, to, ids, values, data);
        }
    }

